-- Live queries behind the Claude dashboard "FeatherLM Human Votes" (Supabase project xbljmithzwcnrjihfgxm,
-- table public.featherlm_ab_votes, insert-only for the public page). Set 1 = version fd809333; in each pair
-- pick 'a' is FeatherLM for pids 1,2,6,8,9,11,17,20 (hackathon/demo/ab_pairs.json). Latest pick per ballot+pid.

-- summary
WITH latest AS (SELECT DISTINCT ON (ballot, pid) id, ballot, pid, pick, vw, reason, at FROM public.featherlm_ab_votes WHERE version LIKE 'fd809333%' ORDER BY ballot, pid, id DESC), v AS (SELECT *, CASE WHEN pick IN ('tie','t') THEN 'Same' WHEN (pick = 'a') = (pid IN (1,2,6,8,9,11,17,20)) THEN 'FeatherLM' ELSE 'Claude' END AS choice FROM latest WHERE pick IN ('a','b','tie','t')), items(pid, item) AS (VALUES (1,'dev-050'),(2,'dev-063'),(3,'dev-028'),(4,'trick-05'),(5,'trick-04'),(6,'dev-054'),(7,'trick-10'),(8,'dev-018'),(9,'dev-065'),(10,'trick-20'),(11,'dev-052'),(12,'dev-066'),(13,'dev-046'),(14,'dev-098'),(15,'dev-075'),(16,'dev-006'),(17,'dev-062'),(18,'dev-034'),(19,'trick-25'),(20,'dev-039')) SELECT count(*)::int AS votes, count(DISTINCT ballot)::int AS readers, count(*) FILTER (WHERE choice = 'FeatherLM')::int AS featherlm, count(*) FILTER (WHERE choice = 'Same')::int AS same, count(*) FILTER (WHERE choice = 'Claude')::int AS claude, count(DISTINCT ballot) FILTER (WHERE vw < 768)::int AS phone_readers, count(*) FILTER (WHERE coalesce(reason, '') <> '')::int AS with_reason, to_char(max(at) AT TIME ZONE 'America/Los_Angeles', 'HH24:MI') AS last_vote_pt, (SELECT count(DISTINCT (ballot, pid))::int FROM public.featherlm_ab_votes WHERE version LIKE '5b878551%') AS round2_picks FROM v;

-- by_pair
WITH latest AS (SELECT DISTINCT ON (ballot, pid) id, ballot, pid, pick, vw, reason, at FROM public.featherlm_ab_votes WHERE version LIKE 'fd809333%' ORDER BY ballot, pid, id DESC), v AS (SELECT *, CASE WHEN pick IN ('tie','t') THEN 'Same' WHEN (pick = 'a') = (pid IN (1,2,6,8,9,11,17,20)) THEN 'FeatherLM' ELSE 'Claude' END AS choice FROM latest WHERE pick IN ('a','b','tie','t')), items(pid, item) AS (VALUES (1,'dev-050'),(2,'dev-063'),(3,'dev-028'),(4,'trick-05'),(5,'trick-04'),(6,'dev-054'),(7,'trick-10'),(8,'dev-018'),(9,'dev-065'),(10,'trick-20'),(11,'dev-052'),(12,'dev-066'),(13,'dev-046'),(14,'dev-098'),(15,'dev-075'),(16,'dev-006'),(17,'dev-062'),(18,'dev-034'),(19,'trick-25'),(20,'dev-039')) SELECT i.pid::int AS pid, i.item, count(*) FILTER (WHERE choice = 'FeatherLM')::int AS featherlm, count(*) FILTER (WHERE choice = 'Same')::int AS same, count(*) FILTER (WHERE choice = 'Claude')::int AS claude, count(*)::int AS votes FROM v JOIN items i ON i.pid = v.pid GROUP BY i.pid, i.item ORDER BY i.pid;

-- readers
WITH latest AS (SELECT DISTINCT ON (ballot, pid) id, ballot, pid, pick, vw, reason, at FROM public.featherlm_ab_votes WHERE version LIKE 'fd809333%' ORDER BY ballot, pid, id DESC), v AS (SELECT *, CASE WHEN pick IN ('tie','t') THEN 'Same' WHEN (pick = 'a') = (pid IN (1,2,6,8,9,11,17,20)) THEN 'FeatherLM' ELSE 'Claude' END AS choice FROM latest WHERE pick IN ('a','b','tie','t')), items(pid, item) AS (VALUES (1,'dev-050'),(2,'dev-063'),(3,'dev-028'),(4,'trick-05'),(5,'trick-04'),(6,'dev-054'),(7,'trick-10'),(8,'dev-018'),(9,'dev-065'),(10,'trick-20'),(11,'dev-052'),(12,'dev-066'),(13,'dev-046'),(14,'dev-098'),(15,'dev-075'),(16,'dev-006'),(17,'dev-062'),(18,'dev-034'),(19,'trick-25'),(20,'dev-039')) SELECT row_number() OVER (ORDER BY min(at))::int AS reader, CASE WHEN max(vw) IS NULL THEN 'Unknown' WHEN max(vw) < 768 THEN 'Phone' ELSE 'Desktop' END AS device, count(*)::int AS answered, count(*) FILTER (WHERE choice = 'FeatherLM')::int AS featherlm, count(*) FILTER (WHERE choice = 'Same')::int AS same, count(*) FILTER (WHERE choice = 'Claude')::int AS claude, to_char(min(at) AT TIME ZONE 'America/Los_Angeles', 'HH24:MI') AS started_pt FROM v GROUP BY ballot ORDER BY reader;

-- reasons
WITH latest AS (SELECT DISTINCT ON (ballot, pid) id, ballot, pid, pick, vw, reason, at FROM public.featherlm_ab_votes WHERE version LIKE 'fd809333%' ORDER BY ballot, pid, id DESC), v AS (SELECT *, CASE WHEN pick IN ('tie','t') THEN 'Same' WHEN (pick = 'a') = (pid IN (1,2,6,8,9,11,17,20)) THEN 'FeatherLM' ELSE 'Claude' END AS choice FROM latest WHERE pick IN ('a','b','tie','t')), items(pid, item) AS (VALUES (1,'dev-050'),(2,'dev-063'),(3,'dev-028'),(4,'trick-05'),(5,'trick-04'),(6,'dev-054'),(7,'trick-10'),(8,'dev-018'),(9,'dev-065'),(10,'trick-20'),(11,'dev-052'),(12,'dev-066'),(13,'dev-046'),(14,'dev-098'),(15,'dev-075'),(16,'dev-006'),(17,'dev-062'),(18,'dev-034'),(19,'trick-25'),(20,'dev-039')) SELECT v.id::int AS n, i.item, v.choice, v.reason, to_char(v.at AT TIME ZONE 'America/Los_Angeles', 'HH24:MI') AS at_pt FROM v JOIN items i ON i.pid = v.pid WHERE coalesce(v.reason, '') <> '' ORDER BY v.at DESC;
